import{_ as t}from"./chunks/image57.pPHO-JgT.js";import{_ as n}from"./chunks/image11.B6ai34I9.js";import{_ as i}from"./chunks/image10.CXG-iZ2X.js";import{_ as a}from"./chunks/2.BRgDBKom.js";import{_ as r,o,c as s,am as l}from"./chunks/framework.CenUaW7a.js";const d="/projects/AiMechaM1/en/advanced-kit/assets/8.D45nnkOn.webp",c="/projects/AiMechaM1/en/advanced-kit/assets/image55.rqpgq2HV.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image56.Boc8aJA8.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image58.CH4m32Uz.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image59.CAI8J6lH.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image60.D789uROi.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image61.ByI6I52H.png",f="/projects/AiMechaM1/en/advanced-kit/assets/image62.DW3pvkhl.png",v="/projects/AiMechaM1/en/advanced-kit/assets/image63.lw3hykOC.png",M=JSON.parse('{"title":"3.8 Lesson 8: Advanced Path Planning","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.8 Lesson 8 Advanced Path Planning.md","filePath":"docs/3. Course materials/3.8 Lesson 8 Advanced Path Planning.md"}'),w={name:"docs/3. Course materials/3.8 Lesson 8 Advanced Path Planning.md"};function y(_,e,x,b,k,S){return o(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="_3-8-lesson-8-advanced-path-planning" tabindex="-1">3.8 Lesson 8: Advanced Path Planning <a class="header-anchor" href="#_3-8-lesson-8-advanced-path-planning" aria-label="Permalink to &quot;3.8 Lesson 8: Advanced Path Planning&quot;">​</a></h1><h2 id="_3-8-1-lesson-introduction" tabindex="-1">3.8.1 Lesson Introduction <a class="header-anchor" href="#_3-8-1-lesson-introduction" aria-label="Permalink to &quot;3.8.1 Lesson Introduction&quot;">​</a></h2><p>Building upon introductory path planning, this lesson enters the advanced domain of curved trajectories and multi-mode coordination. Taking inspiration from S-curve driving tests, curved driving scenarios are simulated. Following the progression of &quot;straight-line drifting → diagonal transition → multi-segment combination → closed curves&quot;, forward movement, drifting, and multi-stage diagonal angles are combined to achieve an S-shaped trajectory, which is then expanded to closed oval paths and continuous loop motion. Translational, diagonal, and drifting modes are comprehensively applied alongside differential speed curvature control. Mastering complex curve planning and multi-mode collaborative programming completes the entire motion control curriculum.</p><h2 id="_3-8-2-learning-objectives" tabindex="-1">3.8.2 Learning Objectives <a class="header-anchor" href="#_3-8-2-learning-objectives" aria-label="Permalink to &quot;3.8.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the principle of linear approximation for complex curves and the concept of smooth transitions across multi-segment connections. Master the kinematic mechanism by which speed differentials between the left and right wheels generate steering curvature. Learn the correspondence between drifting amplitude and wheel speed differentials.</p><p><strong>2.</strong> Master the programming method of multi-stage angular gradients to achieve smooth arc transitions. Independently complete the full advanced path program for S-curve cornering. Expand the program to achieve closed curved trajectories such as ovals and incorporate loop motion.</p><p><strong>3.</strong> Cultivate system design capabilities for coordinating multiple motion modes. Strengthen engineering optimization awareness for parameter tuning and trajectory refinement. Form an initial dynamic mindset connecting differential speed control with trajectory curvature.</p><p><strong>4.</strong> Connect advanced path planning to service robot scenarios. Comprehend the application value of precise trajectory control technology in commercial services and smart logistics. Stimulate interest in exploring robot motion planning and autonomous navigation technologies.</p><h2 id="_3-8-3-preparation" tabindex="-1">3.8.3 Preparation <a class="header-anchor" href="#_3-8-3-preparation" aria-label="Permalink to &quot;3.8.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-wheel robot base × 1</p></li><li><p>Type-C USB data cable × 1</p></li><li><p>Computer running Windows or macOS × 1</p></li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><p><strong>S-Shaped Path Structure Description</strong>: The overall path consists of five parts: an entry straight segment, a first curve segment, a diagonal transition segment, a second curve segment, and an exit straight segment. The curve segments utilize left-right wheel speed differentials to generate drifting turns, while the transition segment uses a multi-stage angular gradient from 5° → 15° → 5° to achieve a smooth connection and avoid abrupt directional changes. Setting the standard teaching demonstration rotational speed to 60 rpm is recommended.</p><p><strong>Wheel Group Control Description</strong>: The speeds of the left wheel group and right wheel group can be set separately to achieve steering with different curvatures via left-right wheel speed differentials. A larger wheel speed differential results in a smaller turning radius and a wider drifting amplitude, whereas a smaller wheel speed differential produces a larger turning radius and a gentler trajectory.</p><h2 id="_3-8-4-hands-on-project" tabindex="-1">3.8.4 Hands-On Project <a class="header-anchor" href="#_3-8-4-hands-on-project" aria-label="Permalink to &quot;3.8.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This project focuses on the S-curve cornering function of the Mecanum-wheel car, adopting a three-layer control logic of &quot;segmented approximation → mode switching → smooth transition&quot;. The continuous S-shaped curve is decomposed into multiple straight-line motion segments, utilizing forward mode for straight paths, drifting mode for high-curvature turns, and gentle diagonal turning mode for low-curvature sections. The system switches between various motion modes in chronological sequence while applying stepped angular gradients and progressive wheel speed differential adjustments to eliminate motion stuttering. By integrating straight driving, diagonal movement, and drifting through discretized approximation and multi-mode coordination, the car achieves a smooth curved trajectory that illustrates the core principles of advanced path planning.</p><img loading="lazy" height="540" width="960" src="'+d+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="633" width="1194" src="'+c+'" class="common_img" style="width:300px;aspect-ratio:1194 / 633;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Distance movement</td><td style="text-align:center;"><img loading="lazy" height="72" width="652" src="'+p+'" class="common_img" style="width:100px;aspect-ratio:652 / 72;"></td><td style="text-align:left;">Forward movement command with a distance parameter for precise displacement on straight segments.</td></tr><tr><td style="text-align:center;">Wheel group control</td><td style="text-align:center;"><img loading="lazy" height="145" width="688" src="'+t+'" class="common_img" style="width:100px;aspect-ratio:688 / 145;"></td><td style="text-align:left;">Independently sets the overall rotational speed of the two left or right wheels for differential steering control.</td></tr><tr><td style="text-align:center;">Simultaneous four-wheel setting</td><td style="text-align:center;"><img loading="lazy" height="59" width="737" src="'+h+'" class="common_img" style="width:600px;aspect-ratio:737 / 59;"></td><td style="text-align:left;">Sets the rotational speeds of all four wheels simultaneously to configure drifting turn modes.</td></tr><tr><td style="text-align:center;">Angular movement</td><td style="text-align:center;"><img loading="lazy" height="81" width="678" src="'+g+'" class="common_img" style="width:100px;aspect-ratio:678 / 81;"></td><td style="text-align:left;">Angular diagonal movement command that achieves smooth transition segments via multi-stage angular gradients.</td></tr><tr><td style="text-align:center;">Loop control</td><td style="text-align:center;"><img loading="lazy" height="276" width="415" src="'+n+'" class="common_img" style="width:100px;aspect-ratio:415 / 276;"></td><td style="text-align:left;">Infinite loop structure used to achieve continuous loop motion along closed trajectories.</td></tr><tr><td style="text-align:center;">Timing control</td><td style="text-align:center;"><img loading="lazy" height="100" width="326" src="'+i+'" class="common_img" style="width:100px;aspect-ratio:326 / 100;"></td><td style="text-align:left;">Sets the duration of each motion segment to control the trajectory length of each section.</td></tr><tr><td style="text-align:center;">Event trigger</td><td style="text-align:center;"><img loading="lazy" height="175" width="527" src="'+m+'" class="common_img" style="width:100px;aspect-ratio:527 / 175;"></td><td style="text-align:left;">Triggers the program via key events, allowing different keys to launch different path programs.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Basic Trajectory Combining Straight and Drifting Segments</strong></p><ul><li><p>Use the <code>When the A key is pressed briefly</code> block as the program trigger entry.</p></li><li><p>Entry straight segment: Set the Mecanum-wheel car to move forward for 10 cm at 60 rpm.</p></li><li><p>Left-turn drifting: Set the front-left wheel to 0 + the rear-left wheel to -60 + the front-right wheel to 0 + the rear-right wheel to 60 to initiate counterclockwise drifting, and wait 5 s.</p></li><li><p>Right-turn drifting: Set the front-left wheel to 0 + the rear-left wheel to 60 + the front-right wheel to 0 + the rear-right wheel to -60 to initiate clockwise drifting, and wait 5 s.</p></li><li><p>Exit straight segment: Set the Mecanum-wheel car to move forward for 10 cm at 60 rpm.</p></li></ul><img loading="lazy" height="271" width="771" src="'+u+'" class="common_img" style="width:300px;aspect-ratio:771 / 271;"><p><strong>Task 2: Complete S-Curve Cornering with Diagonal Segments</strong></p><ul><li><p>Program entry: Triggered when the A key is pressed briefly.</p></li><li><p>Entry straight segment: Move forward 10 cm to prepare for entering the curve.</p></li><li><p>First curve drifting: Apply the counterclockwise drifting configuration and wait 3 s to complete the left turn.</p></li><li><p>Differential transition segment: Set the left wheels to 10 rpm and the right wheels to 60 rpm, and wait 2 s to progressively adjust the curvature.</p></li><li><p>Three-stage diagonal transition segment: Move in the 5° direction for 1 s →move in the 15° direction for 2 s → move in the 5° direction for 1 s → smoothly transition into the reverse curve.</p></li><li><p>Reverse differential transition: Set the left wheels to 60 rpm and the right wheels to 10 rpm, and wait 3 s for a reverse curvature gradient.</p></li><li><p>Second curve drifting: Apply the clockwise drifting configuration and wait 2 s to complete the right turn.</p></li><li><p>Exit straight segment: Move forward 10 cm to exit the curve.</p></li><li><p>Key technique: The multi-stage angular gradient makes directional switching smoother and prevents sharp angles along the trajectory.</p></li></ul><img loading="lazy" height="686" width="758" src="'+f+'" class="common_img" style="width:300px;aspect-ratio:758 / 686;"><p><strong>Extended Task: Closed Oval Path and Loop Motion</strong></p><ul><li><p>Oval structure: Combine two parallel straight segments + two semicircular curve segments to form a four-segment closed oval trajectory.</p></li><li><p>Curve segment: Use left and right wheel group differential control by setting the left side to 40 rpm and the right side to 60 rpm to form a circular arc turn via wheel speed differentials, and wait 6 s.</p></li><li><p>Straight segment: Use the forward movement command with a distance parameter and set the displacement to 40 cm.</p></li><li><p>Curve segment: Use left and right wheel group differential control by setting the left side to 40 rpm and the right side to 60 rpm to form a circular arc turn via wheel speed differentials, and wait 6 s.</p></li><li><p>Straight segment: Use the forward movement command with a distance parameter and set the displacement to 40 cm.</p></li><li><p>Repeat this sequence in a continuous loop.</p></li></ul><img loading="lazy" height="521" width="640" src="'+v+'" class="common_img" style="width:300px;aspect-ratio:640 / 521;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Advanced Path Planning</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+a+'" class="common_img" style="width:600px;aspect-ratio:960 / 508;"><h2 id="_3-8-5-expansion-and-advancement" tabindex="-1">3.8.5 Expansion and Advancement <a class="header-anchor" href="#_3-8-5-expansion-and-advancement" aria-label="Permalink to &quot;3.8.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Closed Figure-8 Curve</strong></p><p>Building upon the S-shaped and oval trajectories, design a complex closed figure-8 curve. Connect two S-shaped curves in opposite directions, combining straight transitions with drifting turns to make the car follow a looping figure-&quot;8&quot; trajectory. Carefully plan the mode-switching points and curvature parameters for each segment to practice advanced programming skills in complex path decomposition and multi-mode coordination, and optionally add a loop block for continuous figure-8 driving.</p><p><strong>Project 2: Curve Speed and Accuracy Comparison Experiment</strong></p><p>Design a comparative experiment to drive the car through the same S-curve at three different rotational speeds: 40 rpm, 60 rpm, and 80 rpm. Record the trajectory deviation, line-crossing occurrences, and completion time at each rotational speed. Summarize the relationship curve between driving speed and cornering accuracy to identify the optimal cornering speed range, cultivating scientific inquiry skills in experimental design and data analysis while understanding the trade-off between speed and accuracy in motion control.</p><h2 id="_3-8-6-q-a" tabindex="-1">3.8.6 Q&amp;A <a class="header-anchor" href="#_3-8-6-q-a" aria-label="Permalink to &quot;3.8.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Why must an S-curve be broken down into multiple motion segments instead of being executed with a single command?</strong></p><p><strong>Answer</strong>: Basic motion control commands execute &quot;uniform straight-line movements&quot; rather than direct curved movements, requiring multiple short straight segments to approximate a continuous curve. In computer graphics and motion control, this method is known as &quot;linear interpolation&quot; or &quot;discretized approximation&quot;.</p><p><strong>Q2: What is the relationship between the left-right wheel speed differential and turning curvature?</strong></p><p><strong>Answer</strong>: The speed differential between the left and right wheels determines the turning radius, which in turn determines the curvature or degree of bending. A larger speed differential produces a smaller turning radius, a greater curvature, and a sharper turn.</p><h2 id="_3-8-7-technical-support-and-discussion" tabindex="-1">3.8.7 Technical Support and Discussion <a class="header-anchor" href="#_3-8-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.8.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',49)])])}const T=r(w,[["render",y]]);export{M as __pageData,T as default};
